frappe.provide("nexus_connect");

frappe.after_ajax(() => {
    const OriginalFileUploader = frappe.ui.FileUploader;

    if (!OriginalFileUploader || OriginalFileUploader.__nexus_overridden) {
        return;
    }

    class NexusFileUploader extends OriginalFileUploader {
        constructor(options = {}) {
            if (
                frappe.session.user === "Guest" &&
                frappe.web_form
            ) {
                options = {
                    ...options,
                    allow_toggle_private: false,
                    make_attachments_public: false,
                };
            }

            super(options);
        }
    }

    NexusFileUploader.__nexus_overridden = true;

    frappe.ui.FileUploader = NexusFileUploader;
});